fn gcd_calc(mut m: u32, mut n: u32) -> u32 {
    // Both m and n are assumed strictly positive.
    // We use the classic Euclidean algorithm with remainder.
    while n != 0 {
        // At this point, m > 0 and n > 0.
        // Let r = m mod n, with 0 <= r < n.
        let r = m % n;
        // After the swap:
        //   m' = n (still > 0)
        //   n' = r (< previous n)
        // Thus the sum m + n strictly decreases each iteration,
        // and we maintain gcd(m, n) = gcd(original m, original n).
        m = n;
        n = r;
    }
    // When n == 0, m is the gcd and still > 0.
    m
}

